    `<span class="meal-label"><span class="ov-text">${timeStr} · 🍽 ${name}</span>${exclMarkHTML(blocks)}</span>` +
    `<span class="meal-resize meal-resize--bottom" data-edge="bottom"></span>`;
  wireMealDrag(band, meal);
  return band;
}

