  if (state.nagsDismissed.has(kind) || heightPx < NAG_MIN_PX) return null;
  const nag = NAGS[kind];
  const { text, partner, url } = nag.link();

  const el = document.createElement("div");
  el.className = "sch-nag";
  el.dataset.nag = kind;

