import { chromium } from "playwright";
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
p.on("pageerror", (e) => console.log("PAGEERROR", e.message));
await p.goto("http://localhost:8765/plan/", { waitUntil: "networkidle" });
await p.waitForTimeout(3000);
const info = await p.evaluate(() => {
  const bands = [...document.querySelectorAll(".sch-meal")].map((b) => ({
    meal: b.dataset.meal, left: b.style.left, right: b.style.right, box: b.getBoundingClientRect().x + "/" + b.getBoundingClientRect().width,
  }));
  const trips = [...document.querySelectorAll(".sch-trip")].map((t) => t.dataset.trip + " " + Math.round(t.getBoundingClientRect().x) + "w" + Math.round(t.getBoundingClientRect().width));
  return { bands, trips, cols: document.querySelectorAll(".sch-day").length };
});
console.log(JSON.stringify(info, null, 1));
await p.screenshot({ path: "/tmp/claude-0/-home-user-EdFringeNow/06bd2c10-a9a8-5c7b-9da8-fc08e25fc06b/scratchpad/before.png", fullPage: true });
await b.close();

